if (module.EntityObservers != null)
{
    RuntimeJson.Require(module.EntityObservers.Count <= RuntimeKernel.MaximumEntityObservers,
        "entity-observer-budget", "Entity observer registration exceeds capacity.");
    foreach (var observer in module.EntityObservers)
    {
        RuntimeJson.Require(RuntimeJson.IsId(observer.Key) && observer.Value != null,
            "entity-observer-namespace", "An entity observer needs a valid namespace and callback.");
        RuntimeJson.Require(next.Resolvers.TryGetValue(observer.Key, out var resolver)
            && resolver.Owner == providerId, "entity-observer-owner",
            "An observer must belong to the owner of its registered entity resolver.");
        RuntimeJson.Require(next.EntityObservers.TryAdd(observer.Key, (providerId, observer.Value!)),
            "entity-observer-conflict", observer.Key);
    }
    RuntimeJson.Require(next.EntityObservers.Count <= RuntimeKernel.MaximumEntityObservers,
        "entity-observer-budget", "Entity observer capacity reached.");
}
next.Validate();
return next;
